<script setup lang="ts">
import Panel from './Panel.vue';
import { computed } from 'vue';
const props=defineProps<{id:string;title:string;description:string;rows:Array<{label:string;total:number}>;kind:'trend'|'distribution'}>();
// Mockup palette: violet, blue, green, amber, rose, teal, slate. Values are always
// printed beside each colour, so colour is never the only carrier of meaning.
const colors=['#7c5cd6','#3b82d6','#2f9e6b','#e0a526','#e0607e','#2aa3a3','#64748b'];
const total=computed(()=>props.rows.reduce((sum,row)=>sum+Number(row.total),0));
const max=computed(()=>Math.max(3,Math.ceil(Math.max(0,...props.rows.map(row=>Number(row.total)))/3)*3));
const x=(index:number)=>40+index*420/Math.max(1,props.rows.length-1);
const y=(value:number)=>170-Number(value)*135/max.value;
const points=computed(()=>props.rows.map((row,index)=>`${x(index)},${y(row.total)}`).join(' '));
const area=computed(()=>props.rows.length?`M${x(0)},170 L${points.value.replaceAll(' ',' L')} L${x(props.rows.length-1)},170 Z`:'');
const offset=(index:number)=>props.rows.slice(0,index).reduce((sum,row)=>sum+Number(row.total),0)/Math.max(1,total.value)*100;
const percent=(value:number)=>total.value?Math.round(Number(value)/total.value*100):0;
</script>
<template><Panel :id="id" :title="title" :description="description"><div v-if="kind==='trend'" class="min-w-0"><svg viewBox="0 0 500 215" class="block w-full" role="img" :aria-label="`${title}. ${total} recorded case openings. See data table below.`"><defs><linearGradient :id="`${id}-fill`" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#7c5cd6" stop-opacity=".18"/><stop offset="100%" stop-color="#7c5cd6" stop-opacity="0"/></linearGradient></defs><g v-for="n in [0,1,2,3]" :key="n"><line x1="40" :y1="170-n*45" x2="460" :y2="170-n*45" stroke="#ece9f5"/><text x="30" :y="174-n*45" text-anchor="end" fill="#64748b" font-size="11">{{Math.round(max*n/3)}}</text></g><path v-if="rows.length>1" :d="area" :fill="`url(#${id}-fill)`"/><polyline :points="points" fill="none" stroke="#7c5cd6" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/><g v-for="(row,index) in rows" :key="row.label"><circle :cx="x(index)" :cy="y(row.total)" r="4.5" fill="#fff" stroke="#7c5cd6" stroke-width="2.5"/><text :x="x(index)" :y="y(row.total)-11" text-anchor="middle" fill="#1f1a3d" font-size="11" font-weight="600">{{row.total}}</text><text :x="x(index)" y="197" text-anchor="middle" fill="#64748b" font-size="11">{{row.label}}</text></g></svg><p v-if="!total" class="text-xs text-slate-600">No case openings recorded in this period.</p></div><div v-else class="flex min-h-[210px] flex-col items-center gap-5 sm:flex-row"><svg viewBox="0 0 120 120" class="h-40 w-40 shrink-0" role="img" :aria-label="`${title}. ${total} authorized cases. See legend and data table.`"><circle cx="60" cy="60" r="44" fill="none" stroke="#efedf6" stroke-width="16"/><circle v-for="(row,index) in rows" :key="row.label" cx="60" cy="60" r="44" pathLength="100" fill="none" :stroke="colors[index%colors.length]" stroke-width="16" :stroke-dasharray="`${Number(row.total)/Math.max(1,total)*100} ${100-Number(row.total)/Math.max(1,total)*100}`" :stroke-dashoffset="-offset(index)" transform="rotate(-90 60 60)"/><text x="60" y="60" text-anchor="middle" fill="#1f1a3d" font-size="22" font-weight="700">{{total}}</text><text x="60" y="76" text-anchor="middle" fill="#64748b" font-size="9">total cases</text></svg><ul class="w-full min-w-0 space-y-2.5 text-sm"><li v-for="(row,index) in rows" :key="row.label" class="flex items-center justify-between gap-3"><span class="flex min-w-0 items-center gap-2 text-slate-700"><span class="h-2.5 w-2.5 shrink-0 rounded-full" :style="{background:colors[index%colors.length]}"/><span class="break-words">{{row.label}}</span></span><span class="shrink-0 text-slate-900"><strong>{{row.total}}</strong> <span class="text-xs text-slate-500">({{percent(row.total)}}%)</span></span></li><li v-if="!rows.length" class="text-slate-600">No case statuses recorded.</li></ul></div><details class="mt-3 border-t border-slate-100 pt-2"><summary class="min-h-11 cursor-pointer py-3 text-xs font-semibold text-brand-700">View data table</summary><table class="w-full text-left text-xs"><caption class="sr-only">{{title}} - authorized records</caption><thead><tr><th scope="col" class="py-2">{{kind==='trend'?'Month':'Recorded status'}}</th><th scope="col" class="py-2 text-right">Cases</th></tr></thead><tbody><tr v-for="row in rows" :key="row.label" class="border-t border-slate-100"><th scope="row" class="py-2 font-normal">{{row.label}}</th><td class="py-2 text-right">{{row.total}}</td></tr></tbody></table></details></Panel></template>
